//! Verifiable Random Function (VRF) Consumer Module.
//!
//! Cryptographically verifies VRF proof signatures generated by an authorized
//! oracle keypair and derives provably fair, unpredictable pseudorandom numbers.

use soroban_sdk::{contracterror, contracttype, panic_with_error, Address, Bytes, BytesN, Env};

use crate::ed25519_verify::Ed25519Verifier;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq, PartialOrd, Ord)]
#[repr(u32)]
pub enum VrfError {
    NotInitialized = 501,
    AlreadyInitialized = 502,
    Unauthorized = 503,
    SeedAlreadyConsumed = 504,
    InvalidRange = 505,
}

#[contracttype]
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum VrfKey {
    Admin,
    OraclePubKey,
    ConsumedSeed(BytesN<32>),
}

pub struct VrfConsumer;

impl VrfConsumer {
    /// Initializes the VRF consumer with an admin and authorized oracle public key.
    pub fn init_oracle(env: &Env, admin: Address, oracle_pubkey: BytesN<32>) {
        admin.require_auth();
        if env.storage().instance().has(&VrfKey::OraclePubKey) {
            panic_with_error!(env, VrfError::AlreadyInitialized);
        }
        env.storage().instance().set(&VrfKey::Admin, &admin);
        env.storage()
            .instance()
            .set(&VrfKey::OraclePubKey, &oracle_pubkey);
    }

    /// Updates the authorized oracle public key. Admin-only.
    pub fn update_oracle(env: &Env, admin: Address, new_oracle_pubkey: BytesN<32>) {
        admin.require_auth();
        let stored_admin: Address = env
            .storage()
            .instance()
            .get(&VrfKey::Admin)
            .unwrap_or_else(|| panic_with_error!(env, VrfError::NotInitialized));

        if admin != stored_admin {
            panic_with_error!(env, VrfError::Unauthorized);
        }
        env.storage()
            .instance()
            .set(&VrfKey::OraclePubKey, &new_oracle_pubkey);
    }

    /// Retrieves the registered oracle public key.
    pub fn get_oracle(env: &Env) -> BytesN<32> {
        env.storage()
            .instance()
            .get(&VrfKey::OraclePubKey)
            .unwrap_or_else(|| panic_with_error!(env, VrfError::NotInitialized))
    }

    /// Verifies VRF proof signature against seed and oracle public key without state mutation.
    /// Returns the deterministic 32-byte VRF output hash: sha256(proof || seed).
    pub fn verify_vrf_proof(
        env: &Env,
        oracle_pubkey: &BytesN<32>,
        seed: &BytesN<32>,
        proof: &BytesN<64>,
    ) -> BytesN<32> {
        let message = Bytes::from_array(env, &seed.to_array());
        Ed25519Verifier::verify(env, oracle_pubkey, &message, proof);

        // Derive deterministic VRF output hash: sha256(proof || seed)
        let mut combined = Bytes::new(env);
        combined.append(&Bytes::from_array(env, &proof.to_array()));
        combined.append(&message);
        env.crypto().sha256(&combined).into()
    }

    /// Verifies VRF proof against registered oracle public key and consumes seed to prevent replay.
    /// Returns the 32-byte VRF random output hash.
    pub fn verify_and_consume_vrf(env: &Env, seed: BytesN<32>, proof: BytesN<64>) -> BytesN<32> {
        let oracle_pubkey = Self::get_oracle(env);
        let key = VrfKey::ConsumedSeed(seed.clone());

        if env.storage().persistent().has(&key) {
            panic_with_error!(env, VrfError::SeedAlreadyConsumed);
        }

        let output = Self::verify_vrf_proof(env, &oracle_pubkey, &seed, &proof);
        env.storage().persistent().set(&key, &output);
        output
    }

    /// Generates an unbiased, provably fair pseudorandom integer in [min, max] from VRF output.
    pub fn generate_fair_random_int(
        env: &Env,
        seed: BytesN<32>,
        proof: BytesN<64>,
        min: u64,
        max: u64,
    ) -> u64 {
        if min > max {
            panic_with_error!(env, VrfError::InvalidRange);
        }
        let output = Self::verify_and_consume_vrf(env, seed, proof);
        Self::bounded_pseudorandom_int(&output, min, max)
    }

    /// Derives an unbiased pseudorandom integer in [min, max] using rejection sampling across 64-bit chunks.
    pub fn bounded_pseudorandom_int(random_bytes: &BytesN<32>, min: u64, max: u64) -> u64 {
        if min == max {
            return min;
        }
        let range = max - min + 1;
        let limit = u64::MAX - (u64::MAX % range);
        let bytes = random_bytes.to_array();

        for chunk in 0..4 {
            let start = chunk * 8;
            let mut buf = [0u8; 8];
            buf.copy_from_slice(&bytes[start..start + 8]);
            let val = u64::from_be_bytes(buf);
            if val < limit {
                return min + (val % range);
            }
        }

        // Deterministic fallback using first 8 bytes if all 4 chunks exceeded limit (probability < 10^-18)
        let mut fallback_buf = [0u8; 8];
        fallback_buf.copy_from_slice(&bytes[0..8]);
        min + (u64::from_be_bytes(fallback_buf) % range)
    }
}
